#!/usr/bin/env node
/* Probe 모의고사 키트 — 실제 Codex 연습용 (Node 18 이상, 외부 패키지 없음)
   node ~/probe-kit.js list                 과제 목록
   node ~/probe-kit.js new <과제> [--b]      모의고사와 똑같은 과제 폴더 만들기 (--b: 연습 B처럼 합의문 포함)
   node ~/probe-kit.js pack [폴더]           제출용 PROBE1 한 줄 만들기 (과제 폴더 안에서 실행)
   node ~/probe-kit.js where                마지막으로 만든 과제 폴더 */
"use strict";
const fs = require("fs"), path = require("path"), zlib = require("zlib"), cp = require("child_process"), os = require("os");
const KIT = "1.0";
const HOME = process.env.PROBE_HOME || path.join(os.homedir(), "probe");
const STATE = path.join(HOME, ".state");
const CODEX_HOME = process.env.CODEX_HOME || path.join(os.homedir(), ".codex");
const BUNDLE = "";
let _sc = null;
const scen = () => _sc || (_sc = JSON.parse(zlib.gunzipSync(Buffer.from(BUNDLE, "base64")).toString("utf8")));
const pad = n => String(n).padStart(2, "0");
const die = msg => { console.error(msg); process.exit(1); };
const git = (dir, args, opt) => cp.spawnSync("git", args, Object.assign({ cwd: dir, encoding: "utf8", maxBuffer: 8 << 20 }, opt || {}));

function list() {
  console.log("과제 목록 (모의고사와 같은 이름)");
  for (const [id, s] of Object.entries(scen())) console.log(`  ${id.padEnd(9)} ${s.sealed ? "봉인 과제 (금요일 실전용 — 열 때 --open)" : s.title + " · " + s.kind}`);
  console.log("\n예: node ~/probe-kit.js new pm        (연습 90 · 실전 — README와 데이터만 있는 빈 상태)\n    node ~/probe-kit.js new pm --b    (연습 B — 합의문만 깔림)");
}

function create(id, flags) {
  const S = scen()[id];
  if (!S) die(`없는 과제예요: ${id || "(빈칸)"}\n목록: node ~/probe-kit.js list`);
  if (S.sealed && flags.b) die("봉인 과제는 연습 B로 못 열어요 — 실전처럼 빈 상태로만 엽니다.\n  node ~/probe-kit.js new " + id + " --open");
  if (S.sealed && !flags.open) die("봉인 과제예요. 금요일 실전 리허설 때 열려면 --open 을 붙이세요.\n  node ~/probe-kit.js new " + id + " --open");
  const d = new Date();
  const name = `${id}-${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}`;
  const dir = path.join(HOME, name);
  if (fs.existsSync(dir)) die("같은 이름 폴더가 이미 있어요: " + dir + "\n1분 뒤 다시 하거나 그 폴더를 쓰세요.");
  const files = Object.assign({}, S.files, flags.b ? S.b : {});
  for (const [p, c] of Object.entries(files)) { const f = path.join(dir, p); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, c); }
  const ok = git(dir, ["init", "-q"]).status === 0;
  if (ok) {
    git(dir, ["config", "user.name", "응시자"]); git(dir, ["config", "user.email", "probe@local"]);
    git(dir, ["add", "-A"]); git(dir, ["commit", "-q", "-m", flags.b ? "시작 상태 (연습 B: 합의문 포함)" : "시작 상태"]);
  }
  fs.mkdirSync(STATE, { recursive: true });
  fs.writeFileSync(path.join(STATE, name + ".json"), JSON.stringify({ id, name, dir, mode: flags.b ? "B" : "full", created: Date.now(), kit: KIT }));
  fs.writeFileSync(path.join(STATE, "last"), dir);
  console.log(`✓ 과제 폴더를 만들었어요: ${dir}`);
  console.log(`  ${S.sealed ? "봉인 과제" : S.title}${flags.b ? " · 연습 B (합의문 포함 — AGENTS.md 8줄은 직접 치기)" : ""}${ok ? " · git 시작 커밋 완료" : " · (git이 없어 커밋 기록은 못 남겨요)"}`);
  console.log("\n다음 순서");
  console.log(`  1) cd ${dir} && codex`);
  console.log('     (경로 복사가 귀찮으면:  cd "$(node ~/probe-kit.js where)" && codex )');
  console.log("  2) codex가 켜지면 먼저 /model — 시험에선 Astra가 제한, 권장 Sol 6.1");
  console.log("  3) 끝나면 이 폴더에서:  node ~/probe-kit.js pack");
  console.log("\n모의고사 화면에서는 같은 과제를 '실제 Codex'로 시작해 두고, 업무 담당자 인터뷰·제출·서술형은 거기서 하세요.");
}

function walk(dir, base, out) {
  for (const n of fs.readdirSync(dir)) {
    if (n === ".git" || n === "node_modules" || n.startsWith(".")) continue;
    const f = path.join(dir, n), st = fs.statSync(f), rel = base ? base + "/" + n : n;
    if (st.isDirectory()) walk(f, rel, out); else out.push({ rel, f, size: st.size });
  }
  return out;
}
function readmeCommands(text) {
  const cmds = [];
  const add = c => { c = c.trim().replace(/^\$\s*/, ""); if (!/^(node|npm)\s/.test(c)) return; if (/[;&`$<>]|\|\|/.test(c)) return; if (/^npm\s+(i|install|ci|start|run\s+(dev|start|serve))\b/.test(c)) return; if (!cmds.includes(c)) cmds.push(c); };
  let inFence = false;
  for (const line of String(text || "").split("\n")) {
    if (/^\s*```/.test(line)) { inFence = !inFence; continue; }
    if (inFence) add(line);
    else for (const m of line.matchAll(/`([^`]+)`/g)) add(m[1]);
  }
  return cmds.slice(0, 5);
}
function runCmd(dir, c) {
  const t0 = Date.now();
  const r = cp.spawnSync("bash", ["-c", c], { cwd: dir, encoding: "utf8", timeout: 15000, maxBuffer: 4 << 20 });
  let out = (r.stdout || "") + (r.stderr ? (r.stdout ? "\n" : "") + r.stderr : "");
  if (r.error && r.error.code === "ETIMEDOUT") out += "\n(15초 시간 초과로 멈춤 — 서버처럼 계속 도는 명령이면 정상일 수 있음)";
  return { cmd: c, code: r.status == null ? 124 : r.status, ms: Date.now() - t0, out: out.length > 3000 ? out.slice(0, 3000) + `\n…(${out.length - 3000}자 생략)` : out };
}
function parseRollout(file) {
  const o = { cwd: null, cli: null, prompts: [], cmds: [], turns: [], tokens: 0, models: [], approvals: 0, agentMsgs: 0, start: null, end: null };
  const seen = new Set(), byId = {};
  let cur = null, last = null, model = null;
  for (const line of fs.readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue;
    let j; try { j = JSON.parse(line); } catch (e) { continue; }
    const p = j.payload && typeof j.payload === "object" ? j.payload : j;
    const ts = Date.parse(j.timestamp || "") || null;
    if (ts) { o.start = o.start || ts; o.end = ts; last = ts; if (cur) cur.e = ts; }
    if (j.type === "session_meta") { o.cwd = o.cwd || p.cwd || null; o.cli = p.cli_version || o.cli; }
    if (j.type === "turn_context") {
      o.cwd = o.cwd || p.cwd || null;
      const eff = p.collaboration_mode && p.collaboration_mode.settings ? p.collaboration_mode.settings.reasoning_effort : (p.effort || p.reasoning_effort);
      model = (p.model || model || "") + (eff ? " " + eff : "");
      if (model && !o.models.includes(model)) o.models.push(model);
    }
    let ut = null;
    if (j.type === "event_msg" && p.type === "user_message" && typeof p.message === "string") ut = p.message;
    else if (p.type === "message" && p.role === "user" && Array.isArray(p.content)) ut = p.content.map(c => c.text || "").join("\n");
    else if (j.type === "event_msg" && p.type === "item_completed" && p.item && /^user_?message$/i.test(p.item.type || "") && Array.isArray(p.item.content)) ut = p.item.content.map(c => c.text || "").join("\n");
    if (ut != null) {
      const t = ut.trim();
      if (t && !/^<(environment_context|user_instructions|user_shell_command|turn_aborted)/.test(t) && !/^# AGENTS\.md instructions/.test(t)) {
        const k = t.slice(0, 300);
        if (!seen.has(k)) { seen.add(k); o.prompts.push({ at: ts || last, text: t.length > 2500 ? t.slice(0, 2500) + "…" : t, model }); cur = { s: ts || last, e: ts || last }; o.turns.push(cur); }
      }
    }
    if ((p.type === "function_call" && /shell|exec/i.test(p.name || "")) || p.type === "local_shell_call") {
      let c = "";
      try { const a = p.type === "local_shell_call" ? (p.action || {}) : JSON.parse(p.arguments || "{}"); c = a.cmd || (Array.isArray(a.command) ? a.command[a.command.length - 1] : a.command) || ""; } catch (e) { c = String(p.arguments || ""); }
      const x = { at: ts || last, cmd: String(c).slice(0, 300) }; o.cmds.push(x); if (p.call_id) byId[p.call_id] = x;
    }
    if (p.type === "custom_tool_call" && /apply_patch/.test(p.name || "")) {
      const fsTouched = (String(p.input || "").match(/\*\*\* (Add|Update|Delete) File: .+/g) || []).map(s => s.replace("*** ", "")).join(", ");
      const x = { at: ts || last, cmd: "apply_patch " + fsTouched.slice(0, 280), patch: true }; o.cmds.push(x); if (p.call_id) byId[p.call_id] = x;
    }
    if ((p.type === "function_call_output" || p.type === "custom_tool_call_output") && byId[p.call_id]) {
      const x = byId[p.call_id]; let text = "";
      if (typeof p.output === "string") { try { const v = JSON.parse(p.output); text = String(v.output || ""); if (v.metadata && v.metadata.exit_code != null) x.code = v.metadata.exit_code; } catch (e) { text = p.output; } }
      else if (p.output && typeof p.output === "object") { text = String(p.output.content || p.output.output || ""); }
      const m = text.match(/(?:Exit code|exited with code)[:\s]+(-?\d+)/i); if (x.code == null && m) x.code = +m[1];
      const pm = text.match(/^# pass (\d+)/m), fm = text.match(/^# fail (\d+)/m); if (pm) x.pass = +pm[1]; if (fm) x.fail = +fm[1];
    }
    if (j.type === "event_msg" && p.type === "token_count" && p.info && p.info.total_token_usage) o.tokens = Math.max(o.tokens, +p.info.total_token_usage.total_tokens || 0);
    if (j.type === "event_msg" && /approval_request$/.test(p.type || "")) o.approvals++;
    if (j.type === "event_msg" && p.type === "agent_message") o.agentMsgs++;
  }
  return o;
}
function codexSessions(dir, since) {
  const root = path.join(CODEX_HOME, "sessions"), found = [];
  const rec = d => { let ns; try { ns = fs.readdirSync(d); } catch (e) { return; } for (const n of ns) { const f = path.join(d, n); let st; try { st = fs.statSync(f); } catch (e) { continue; } if (st.isDirectory()) rec(f); else if (/\.jsonl$/.test(n) && st.mtimeMs >= since - 5 * 60000) found.push(f); } };
  rec(root);
  let real = dir; try { real = fs.realpathSync(dir); } catch (e) { }
  const inDir = c => c && (c === dir || c === real || c.startsWith(dir + path.sep) || c.startsWith(real + path.sep));
  const res = { sessions: 0, cli: null, prompts: [], cmds: [], turns: [], tokens: 0, models: [], approvals: 0, agentMsgs: 0, scanned: found.length };
  for (const f of found) {
    let s; try { s = parseRollout(f); } catch (e) { continue; }
    if (!inDir(s.cwd)) continue;
    res.sessions++; res.cli = s.cli || res.cli;
    res.prompts.push(...s.prompts); res.cmds.push(...s.cmds); res.turns.push(...s.turns);
    res.tokens += s.tokens; res.approvals += s.approvals; res.agentMsgs += s.agentMsgs;
    for (const m of s.models) if (!res.models.includes(m)) res.models.push(m);
  }
  res.prompts.sort((a, b) => a.at - b.at); res.cmds.sort((a, b) => a.at - b.at); res.turns.sort((a, b) => a.s - b.s);
  if (res.cmds.length > 150) res.cmds = res.cmds.slice(-150);
  return res;
}
function pack(arg, flags) {
  let dir = path.resolve(arg || process.cwd());
  if (!fs.existsSync(path.join(dir, "README.md"))) {
    let up = dir; while (up !== path.dirname(up) && !fs.existsSync(path.join(up, "README.md"))) up = path.dirname(up);
    if (fs.existsSync(path.join(up, "README.md")) && up.startsWith(HOME)) dir = up; else die("과제 폴더 안에서 실행하세요 (README.md가 있는 폴더).\n마지막 과제 폴더: " + (fs.existsSync(path.join(STATE, "last")) ? fs.readFileSync(path.join(STATE, "last"), "utf8") : "없음"));
  }
  let st = {}; try { st = JSON.parse(fs.readFileSync(path.join(STATE, path.basename(dir) + ".json"), "utf8")); } catch (e) { }
  const S = st.id ? scen()[st.id] : null;
  const files = {}, skipped = []; let budget = 400000;
  for (const x of walk(dir, "", []).sort((a, b) => a.size - b.size)) {
    if (S && S.files[x.rel] != null) { const c = fs.readFileSync(x.f, "utf8"); if (c === S.files[x.rel]) continue; }
    if (x.size > 300000 || x.size > budget) { skipped.push(x.rel + ` (${Math.round(x.size / 1024)}KB)`); continue; }
    const buf = fs.readFileSync(x.f); if (buf.includes(0)) { skipped.push(x.rel + " (바이너리)"); continue; }
    files[x.rel] = buf.toString("utf8"); budget -= x.size;
  }
  const commits = [];
  const lg = git(dir, ["log", "--reverse", "--format=%x1e%h%x1f%at%x1f%s", "--name-status"]);
  if (lg.status === 0) for (const rec of lg.stdout.split("\x1e").slice(1)) {
    const ls = rec.split("\n"); const [hash, at, msg] = ls[0].split("\x1f");
    commits.push({ hash, at: +at * 1000, msg, changes: ls.slice(1).filter(Boolean).map(l => { const [type, ...ps] = l.split("\t"); return { type: type[0], p: ps[ps.length - 1] }; }) });
  }
  const gs = git(dir, ["status", "--porcelain"]); const status = gs.status === 0 ? gs.stdout.split("\n").filter(Boolean) : [];
  const runs = readmeCommands(files["README.md"] != null ? files["README.md"] : (S ? S.files["README.md"] : "")).map(c => runCmd(dir, c));
  const codex = codexSessions(dir, st.created || (commits[0] ? commits[0].at : Date.now() - 6 * 3600e3));
  const data = { v: 1, kit: KIT, id: st.id || null, mode: st.mode || null, created: st.created || null, packed: Date.now(), dir, files, skipped, commits, status, runs, codex };
  const json = JSON.stringify(data);
  const token = flags.raw ? "PROBE0:" + Buffer.from(json, "utf8").toString("base64") + ":END" : "PROBE1:" + zlib.gzipSync(Buffer.from(json, "utf8"), { level: 9 }).toString("base64") + ":END";
  fs.mkdirSync(HOME, { recursive: true });
  fs.writeFileSync(path.join(HOME, "last-pack.txt"), token + "\n");
  let www = "";
  if (flags.www && fs.existsSync("/root/www")) { fs.writeFileSync("/root/www/probe-pack.txt", token + "\n"); www = "/root/www/probe-pack.txt"; }
  const warn = [];
  if (!st.id) warn.push("이 폴더는 키트로 만든 기록이 없어요 — 과제 이름을 모르는 채로 가져가요.");
  if (status.length) warn.push(`커밋 안 된 변경 ${status.length}개 (${status.slice(0, 4).map(s => s.slice(3)).join(", ")}${status.length > 4 ? " …" : ""}) — 파일은 가져가지만 git 기록엔 없어요.`);
  if (!codex.sessions) warn.push(`이 폴더에서 돌린 Codex 기록을 못 찾았어요 (${CODEX_HOME}/sessions, 최근 파일 ${codex.scanned}개 확인). Codex를 이 폴더에서 실행했는지 확인하세요.`);
  if (!runs.length) warn.push("README에서 실행할 node 명령을 못 찾았어요 — 채점 때 실행 검증이 약해져요. README에 `node ...` 실행법을 적어 두세요.");
  if (skipped.length) warn.push("너무 커서 뺀 파일: " + skipped.join(", "));
  console.log("──────── 아래 PROBE 줄 전체를 복사해서 모의고사 '제출' 칸에 붙여넣기 ────────");
  console.log(token);
  console.log(`──────── 파일 ${Object.keys(files).length} · 커밋 ${commits.length} · Codex 지시 ${codex.prompts.length} · Codex 명령 ${codex.cmds.length} · README 명령 ${runs.length} · ${(token.length / 1024).toFixed(1)}KB ────────`);
  for (const w of warn) console.log("! " + w);
  console.log(`(같은 내용을 ${path.join(HOME, "last-pack.txt")} 에도 저장했어요${www ? ", " + www + " 에도" : ""}. Termius에서 복사가 어려우면: node ~/probe-kit.js pack --www → 8420 서버의 /probe-pack.txt 를 폰 브라우저로 열어 복사)`);
}

const [cmd, ...rest] = process.argv.slice(2);
const flags = { b: rest.includes("--b"), open: rest.includes("--open"), raw: rest.includes("--raw"), www: rest.includes("--www") };
const pos = rest.filter(x => !x.startsWith("--"));
if (cmd === "list") list();
else if (cmd === "new") create(pos[0], flags);
else if (cmd === "pack") pack(pos[0], flags);
else if (cmd === "where") console.log(fs.existsSync(path.join(STATE, "last")) ? fs.readFileSync(path.join(STATE, "last"), "utf8") : "아직 만든 과제 폴더가 없어요");
else if (cmd === "version" || cmd === "-v") console.log("probe-kit " + KIT);
else { console.log("Probe 모의고사 키트 " + KIT + "\n  node ~/probe-kit.js list\n  node ~/probe-kit.js new <과제> [--b]\n  node ~/probe-kit.js pack\n  node ~/probe-kit.js where"); }
